"""The offline material one party holds when the online phase starts (dealt by a trusted dealer over the mesh, or generated by the parties
themselves from oblivious transfer with no dealer), plus the shared protocol-level types (test misbehaviour, the silent-party marker).
Port of the reference's net/prep.ts."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, List, Optional

from .mpc_net import AW, PA, SlotDisclosure

T_M = 3  # thermometer width of the tolerance field t


def sharings_per_triple(partners: int) -> int:
    """a, b, c, then (a-hat, c-hat) for each sacrifice partner."""
    return 3 + 2 * partners


class SilentParty(Exception):
    """Raised by the test-only `silent` behaviour; the host then idles with its sockets open (peers must time out)."""


class CrashParty(Exception):
    """Raised by the test-only `crash` behaviour; the host closes the node's sockets abruptly (no abort frame)."""


@dataclass
class Behavior:
    """Test-only protocol-level misbehaviour for a (malicious) party; never set in production. kinds: open-lie, mac-lie, bad-tag, sigma-lie,
    offline-lie, ot-u-lie, ot-proof-lie, equivocate, bad-coin-open, bad-sigma-open, short-array, noncanonical, crash, silent."""

    kind: str
    round: Optional[str] = None


@dataclass
class Forensics:
    """no-dealer only: the OT transcript of the triple products, to attribute a failed sacrifice. rows = choice bits per product item (the
    encoded width); slots = product slots per triple; disclose(t) = my disclosure (list of SlotDisclosure) for triple t."""

    gadget: List[int]
    rows: int
    slots: int
    disclose: Callable[[int], List[SlotDisclosure]]


@dataclass
class Prep:
    """mode: 'trusted-dealer' | 'no-dealer'. tagged: shares carry pairwise tags (identifiable abort; both modes: the no-dealer phase builds them from OT). delta: my pairwise
    verification key (0 when untagged). alpha: my share of each global MAC key (PA). triples[t] = [a, b, c, a_hat_1, c_hat_1, ...] (AW).
    inputs[owner * C + c]: dealer mode the authenticated masks r (owner broadcasts x - r); no-dealer the authenticated input bits. my_plain: my
    plaintext side (masks r / my input bits), one per chain. check_mask: no-dealer only, a random authenticated mask for the input check."""

    mode: str
    tagged: bool
    delta: int
    alpha: List[PA]
    triples: List[List[AW]]
    inputs: List[AW]
    my_plain: List[int]
    check_mask: Optional[AW] = None
    forensics: Optional[Forensics] = None
